          .where((l) => !l.contains('session_repo.dart'))
          .take(3)
          .map((l) => l.trim())
          .join(' <- ');
      timingLog!.call(
        'resume_timing open-caller file=${metadata.path.split('/').last} $frames',
      );
    }
    return Session(
      windowed
          ? await WindowedSessionStorage.open(
              _fs,
              metadata.path,
              parseExecutor: _parseExecutor,
              ioRetry: _ioRetry,
              timingLog: timingLog,
