  before,

  /// The fork contains the entry itself and everything before it.
  at,
}

/// Options for [JsonlSessionRepo.create].
///
/// Ported from pi's `JsonlSessionCreateOptions`.
final class JsonlSessionCreateOptions {
  /// Creates [JsonlSessionCreateOptions].
  const JsonlSessionCreateOptions({
    required this.cwd,
    this.id,
    this.parentSessionPath,
    this.metadata,
  });

  /// Working directory the session belongs to (determines its directory).
  final String cwd;

  /// Explicit session id; a fresh uuidv7 is generated when omitted.
  final String? id;

  /// Path of the parent session (set automatically by [JsonlSessionRepo.fork]).
  final String? parentSessionPath;

  /// Free-form application metadata written to the header.
  final Map<String, dynamic>? metadata;
}

/// The repository contract for sessions.
///
/// Ported from pi's `SessionRepo` (specialized to JSONL metadata/options).
abstract interface class SessionRepo {
  /// Creates a new session.
  Future<Session> create(JsonlSessionCreateOptions options);

  /// Opens an existing session from its metadata. With [windowed] only
  /// the header plus the newest chunk are materialized; with
  /// [wholeFileOnly] the full open takes the classic whole-file read even
  /// on a ranged filesystem (error-recovery fallbacks: a retry after a
  /// ranged-read failure must not depend on that capability again).
  Future<Session> open(
    SessionMetadata metadata, {
    bool windowed = false,
    bool wholeFileOnly = false,
  });

  /// Lists stored sessions, newest first; [cwd] filters to one directory.
  Future<List<SessionMetadata>> list({String? cwd});

  /// Deletes a session file.
  ///
  /// Issue #522: the delete is journaled (who/what/when into the root's
  /// `session_ops.journal`), soft (the file moves into `<root>/.trash/`),
  /// and refused with [SessionErrorCode.liveSession] while a fresh
  /// presence row exists for the session — unless the deleting process
  /// owns that row. [actor] names the calling flow for the journal.
  Future<void> delete(SessionMetadata metadata, {String actor = 'unknown'});

  /// Forks [source] into a new session containing a prefix of its tree.
  ///
  /// When [entryId] is given, the fork contains the branch ending at that
  /// entry ([ForkPosition.at]) or everything before it, which requires the
  /// entry to be a user message ([ForkPosition.before], the default).
  Future<Session> fork(
    SessionMetadata source, {
    required String cwd,
    String? entryId,
    ForkPosition position,
    String? id,
    String? parentSessionPath,
    Map<String, dynamic>? metadata,
  });
}

String _encodeCwd(String cwd) {
  final normalized = cwd.replaceAll(RegExp(r'[/\\]+$'), '');
  final bare = normalized.replaceFirst(RegExp(r'^[/\\]'), '');
  // Reversible escaping (gh-1744): separators still flatten to `-`, but a
  // literal `-` must not be mistaken for one, so it (and every character
  // the decoder treats specially) rides percent-escapes BEFORE the
  // separator flattening. Paths without any of them encode
  // byte-identically to the legacy scheme, keeping existing on-disk slug
  // folders and pi's layout stable.
  final escaped = bare
      .replaceAll('%', '%25')
      .replaceAll('-', '%2D')
      .replaceAll(':', '%3A')
      .replaceAll(RegExp(r'[/\\]'), '-');
  return '--$escaped--';
}

/// The per-project directory slug used under the sessions root
/// (`/work` → `--work--`). Public so sibling stores (e.g. the messaging
/// fabric root) colocate with the project's sessions.
String encodeSessionCwd(String cwd) => _encodeCwd(cwd);

/// The escape sequences [decodeSessionCwd] understands. `%2D` (a literal
/// hyphen) is what makes the scheme reversible: without it, hyphens in
/// directory names decoded as path separators (gh-1744).
final RegExp _slugEscape = RegExp(r'%([0-9A-Fa-f]{2})');

/// Whether [inner] carries a reversible escape — the marker that the slug
/// was written by the reversible encoder and must not go through the
/// legacy lossy split.
bool _hasReversibleEscape(String inner) => _slugEscape
    .allMatches(inner)
    .any((m) => const {'25', '2D', '2F', '5C', '3A'}
        .contains(m.group(1)!.toUpperCase()));

/// Undoes [_encodeCwd]'s percent-escapes in one segment. Unknown `%XX`
/// sequences stay literal (legacy text).
String _unescapeSlugPart(String part) => part.replaceAllMapped(
  _slugEscape,
  (m) => switch (m.group(1)!.toUpperCase()) {
    '25' => '%',
    '2D' => '-',
    '2F' => '/',
    '5C' => r'\',
    '3A' => ':',
    _ => m.group(0)!,
  },
);

/// Reverses [encodeSessionCwd]: `--Users-Uladzimir_Klyshevich-git-dm.ai--`
/// → `/Users/Uladzimir_Klyshevich/git/dm.ai`.
///
/// Slugs written by the reversible encoder (they carry `%2D`-style
/// escapes, gh-1744) decode exactly; legacy escape-free slugs keep the
/// historic lossy split-on-hyphen decode so existing on-disk folders stay
/// readable.
///
/// Second legacy ambiguity class (gh-1744 review): the reversible marker
/// is "the slug carries a recognized `%XX` escape", so a legacy folder
/// whose name legitimately contained escape-like TEXT flips its decode —
/// `%2D`, `%2F`, `%5C`, `%3A` and `%25` present in legacy slug text now
/// unescape (e.g. `--tmp-a%2Fb--` decoded literally before this change,
/// and decodes to `/tmp/a/b` now; `--tmp-a%2Db--` → `/tmp/a-b`;
/// `--tmp-a%25b--` → `/tmp/a%b`). Impact is bounded: the decode only
/// feeds the messaging `directory()` cwd fallback — the registry's exact
/// cwd is preferred — and a wrong fallback cwd is refused by name in
/// [launchMailboxWake] instead of crashing the wake.
///
/// Returns `null` if [slug] is not wrapped in `--` or decodes to an empty path.
String? decodeSessionCwd(String slug) {
  if (slug.length < 4 || !slug.startsWith('--') || !slug.endsWith('--')) {
    return null;
  }
  final inner = slug.substring(2, slug.length - 2);
  if (inner.isEmpty) return null;
  final reversible = _hasReversibleEscape(inner);
  final parts = inner.split('-');
  if (parts.isEmpty || parts.any((p) => p.isEmpty)) return null;
  if (!reversible) return '/${parts.join('/')}';
  return '/${parts.map(_unescapeSlugPart).join('/')}';
}

/// Creates a new session id (time-ordered uuidv7).
String createSessionId() => uuidv7();

/// Sorts by latest activity (file mtime), falling back to creation time so
/// stable ordering is guaranteed even when mtimes are equal.
int compareSessionActivity(SessionMetadata a, SessionMetadata b) {
  final aTime = a.lastUpdatedAt ?? a.createdAt;
  final bTime = b.lastUpdatedAt ?? b.createdAt;
  final result = bTime.compareTo(aTime);
  if (result != 0) return result;
  return b.createdAt.compareTo(a.createdAt);
}

