/// The `.trash` directory under the sessions root (issue #522): deleted
/// session files land here — `<root>/.trash/<timestamp>_<name>` — and
/// stay recoverable until [purgeTrash] drops them past a TTL.
static const String trashDirName = '.trash';

/// The per-root deletion journal (issue #522): one JSON line per
/// delete/move/purge with the culprit (pid + actor tag), the path, and
/// the outcome. A vanished session file always has a named record.
static const String journalFileName = 'session_ops.journal';

/// Moves [path] into `<root>/.trash/` and journals the operation.
///
/// Trash-first: the move is atomic, so a crash can only leave the file
/// recoverable in `.trash` (its presence there IS the record) or in
/// place — never gone. Backends without a rename primitive (pure web)
/// fall back to a journaled remove: the intent line lands BEFORE the
/// unlink so even that path names its culprit.
///
/// Issue #863: a rename that fails as `notSupported` (a decorator env
/// advertising the capability its delegate lacks) falls back to
/// copy+delete so the session is still really deleted, and every
/// success path is verified — a backend that reports success but left
/// the file in place raises instead of passing as a silent no-op.
Future<void> _softDelete(
  String path, {
  required String op,
  String? sessionId,
  required String actor,
}) async {
  final root = await _getSessionsRoot();
  final exists = _fsOrThrow(
    await _fs.exists(path),
    'Failed to check session $path',
  );
  if (!exists) {
    await _journal(
      root,
      op: op,
      path: path,
      sessionId: sessionId,
      actor: actor,
      result: 'missing',
    );
    return;
  }
  final trashPath = await _trashPathFor(root, path);
  if (_fs is! RenamableFileSystem) {
    await _journal(
      root,
      op: op,
      path: path,
      sessionId: sessionId,
      actor: actor,
      result: 'remove-fallback',
    );
    _fsOrThrow(
      await _fs.remove(path, force: true),
      'Failed to delete session $path',
    );
    await _verifyGone(path);
    return;
  }
  final trashDir = _fsOrThrow(
    await _fs.joinPath([root, trashDirName]),
    'Failed to resolve trash directory',
  );
  _fsOrThrow(
    await _fs.createDir(trashDir, recursive: true),
    'Failed to create trash directory',
  );
  final renamed = await (_fs as RenamableFileSystem).renamePath(
    path,
    trashPath,
  );
  if (renamed.isErr) {
    final error = renamed.errorOrNull!;
    if (error.code != FileErrorCode.notSupported) {
      _fsOrThrow(renamed, 'Failed to move session $path to trash $trashPath');
    }
    // The decorator/rename gap behind issue #863 ("renamePath not
    // supported by Instance of 'LocalExecutionEnv'"): copy+delete so the
    // delete happens for real — trash copy first, then the unlink, both
    // journaled via the intent line below.
    final info = _fsOrThrow(
      await _fs.fileInfo(path),
      'Failed to stat session $path for the trash copy',
    );
    if (info.size > maxTrashCopyBytes) {
      // The fallback stages the trash copy in RAM (no streaming write
      // on the FileSystem interface); refuse oversized sessions instead
      // of spiking a low-RAM device (issue #863 review).
      throw SessionException(
        'Session $path (${info.size} bytes) is too large to stage the '
        'trash copy on a rename-less backend (limit $maxTrashCopyBytes '
        'bytes); delete it from a host with rename support',
        code: SessionErrorCode.storage,
      );
    }
    await _journal(
      root,
      op: op,
      path: path,
      sessionId: sessionId,
      actor: actor,
      result: 'copy-delete',
    );
    final bytes = _fsOrThrow(
      await _fs.readBinaryFile(path),
      'Failed to read session $path for the trash copy',
    );
    _fsOrThrow(
      await _fs.writeBinaryFile(trashPath, bytes),
      'Failed to write trash copy $trashPath',
    );
    _fsOrThrow(
      await _fs.remove(path, force: true),
      'Failed to delete session $path',
    );
  } else {
    await _journal(
      root,
      op: op,
      path: path,
      sessionId: sessionId,
      actor: actor,
      result: 'trash',
      trash: trashPath,
    );
  }
  await _verifyGone(path);
}

/// Issue #863 (E3): a delete that "succeeded" but left the file (env/repo
/// path mismatch, lying backend) is a named failure — never a silent
/// success.
Future<void> _verifyGone(String path) async {
  final gone = _fsOrThrow(
    await _fs.exists(path),
    'Failed to verify deletion of session $path',
  );
  if (gone) {
    throw SessionException(
      'Session $path still exists after delete — the backend reported '
      'success but removed nothing',
      code: SessionErrorCode.storage,
    );
  }
}

/// `<root>/.trash/<timestamp>_<basename>` — the stamp keeps repeated
/// deletions of the same-named file apart.
Future<String> _trashPathFor(String root, String path) async {
  final stamp = now().toIso8601String().replaceAll(RegExp(r'[:.]'), '-');
  final base = path.split(RegExp(r'[/\\]')).last;
  return _fsOrThrow(
    await _fs.joinPath([root, trashDirName, '${stamp}_$base']),
    'Failed to resolve trash path for $path',
  );
}

/// Appends one auditable line to the root's `session_ops.journal`.
Future<void> _journal(
  String root, {
  required String op,
  required String path,
  String? sessionId,
  required String actor,
  required String result,
  String? trash,
}) async {
  final line = json_conv.jsonEncode({
    'at': now().toIso8601String(),
    'op': op,
    'path': path,
    'session': ?sessionId,
    'pid': ?processId,
    'actor': actor,
    'result': result,
    'trash': ?trash,
  });
  final journalPath = _fsOrThrow(
    await _fs.joinPath([root, journalFileName]),
    'Failed to resolve journal path',
  );
  _fsOrThrow(
    await _fs.appendFile(journalPath, '$line\n'),
    'Failed to append session ops journal $journalPath',
  );
}

/// Removes trash entries older than [ttl] (issue #522): trash is
/// recoverable storage with a lifetime, not an unbounded second copy of
/// every deleted session. Returns the number of entries purged; every
/// purge is journaled.
Future<int> purgeTrash({
  Duration ttl = const Duration(days: 30),
  String actor = 'repo:purge-trash',
}) async {
  final root = await _getSessionsRoot();
  final trashDir = _fsOrThrow(
    await _fs.joinPath([root, trashDirName]),
    'Failed to resolve trash directory',
  );
  if (!_fsOrThrow(await _fs.exists(trashDir), 'Failed to check $trashDir')) {
    return 0;
  }
  final entries = _fsOrThrow(
    await _fs.listDir(trashDir),
    'Failed to list $trashDir',
  );
  final cutoffMs = now().subtract(ttl).millisecondsSinceEpoch;
  var purged = 0;
  for (final entry in entries) {
    if (entry.mtimeMs >= cutoffMs) continue;
    _fsOrThrow(
      await _fs.remove(entry.path, force: true),
      'Failed to purge ${entry.path}',
    );
    await _journal(
      root,
      op: 'purge',
      path: entry.path,
      actor: actor,
      result: 'removed',
    );
    purged++;
  }
  return purged;
}

