  }
  var wireDump = false;
  for (final key in node.keys) {
    if (key != 'wireDump') {
      throw ConfigException('unknown "trajectory" key: $key');
    }
    final value = node[key];
    if (value is! bool) {
      throw ConfigException('"trajectory.wireDump" must be a boolean');
    }
    wireDump = value;

