  /// AC11: a preview bound below the minimum is clamped (with a note).
  static (int, int) _clampPreviewBounds(
    int headChars,
    int tailChars,
    List<String> notes,
  ) {
    var head = headChars;
    var tail = tailChars;
    if (head < spillsMinPreviewChars) {
