    final notes = <String>[];
    bool enabled = true;
    var threshold = 8192;
    var headChars = 2000;
    var tailChars = 2000;
    node.forEach((key, value) {
      switch ('$key') {
        case 'enabled':
          if (value is bool) {
            enabled = value;
          } else {
            notes.add('spills.enabled: not a boolean, default applied');
          }
        case 'threshold':
          threshold = _intWithNote(value, 8192, 'spills.threshold', notes);
        case 'headChars':
