Future<Map<String, String>> sessionDisplayNames(
  SessionRepo repo,
  List<SessionMetadata> sessions,
) async {
  // Issue #199: the concrete JSONL repo scans tails backward with a
  // bounded fan-out — no open at all per session. Other repos keep the
  // windowed-open fallback.
  if (repo is JsonlSessionRepo) return repo.sessionNamesQuick(sessions);
  final names = <String, String>{};
  for (final metadata in sessions) {
    try {
      final name = await (await repo.open(
        metadata,
        windowed: true,
      )).resolveSessionName();
      if (name != null && name.isNotEmpty) names[metadata.id] = name;
    } on Object {
      // Unreadable session: its row degrades to the bare id.
    }
  }
  return names;
}

