      threshold: threshold,
      headChars: clampedHead,
      tailChars: clampedTail,
      notes: List.unmodifiable(notes),
    );
  }

  /// AC11: a preview bound below the minimum is clamped (with a note).
  static (int, int) _clampPreviewBounds(
    int headChars,
