    final content = file.readAsStringSync();
    final doc = loadYaml(content);
    if (doc is YamlMap) {
      final config = CliConfig.fromYaml(doc);
      _warnCanonicalizedProvider(doc, config);
      _warnDroppedGhostProviders(doc, config);
