          notes.add('sessions.retention.$key: unknown key (ignored)');
      }
    });
    return SessionRetentionConfig(
      maxTotalBytes: maxTotalBytes,
      minAgeDays: minAgeDays,
      keepNamed: keepNamed,
      sweep: sweep,
      notes: List.unmodifiable(notes),
    );
  }

  static int _intWithNote(
    Object? value,
    int fallback,
    String name,
    List<String> notes,
