              '(no cap)',
            );
            maxTotalBytes = 0;
          }
        case 'minAgeDays':
          minAgeDays = _intWithNote(
            value,
            defaultMinAgeDays,
            'sessions.retention.minAgeDays',
            notes,
          );
          if (minAgeDays < 0) {
            notes.add(
              'sessions.retention.minAgeDays: negative, clamped to 0',
            );
            minAgeDays = 0;
          }
