### Sweep data model

```dart
/// One session's on-disk footprint (the sweep unit).
final class SessionDiskUsage {
 final String sessionId; final String path; final String? cwd;
 final int bytes; // whole unit: primary + segments + sidecars + usage dir
 final DateTime createdAt; final DateTime lastUsedAt;
}

final class SessionUsageSnapshot {
 final List<SessionDiskUsage> sessions;
 final int totalBytes;
 final List<String> notes; // walk anomalies (skipped symlinks etc.)
}

enum SessionExemption { live, named, tooYoung, current, ... }
Reason strings for plan entries: 'over-cap' for deletions; exemptions carry exemption kind.

final class SweepAction {
 final String sessionId; final String path; final int bytes; final int ageDays; final String reason; // 'over-cap' | exemption label
 final bool delete; // planned deletion vs blocker listing
}

final class SessionSweepReport {
 final bool capConfigured;
 final int totalBytes; final int capBytes;
 final List<SweepAction> deletions; // planned OR applied
 final List<SweepAction> blockers; // exempt, with sizes, when still over cap
 final int freedBytes; final int remainingBytes;
 final bool dryRun;
 final List<String> logLines; // the AC7 lines (deletions + skips)
 final List<String> notes;
}
