      SessionDiskUsage(
        sessionId: sessionId,
        path: entry.path,
        bytes: bytes,
        spillBytes: spillBytes,
        cwd: header.cwd,
        createdAt: header.createdAt,
        lastUsedAt: lastUsed,
      ),
    );
  }
  return sessions;
}

Future<int> _fileBytes(String path) async {
  final info = (await _fs.fileInfo(path)).valueOrNull;
  return info != null && info.kind == FileKind.file ? info.size : 0;
}

