          if (maxTotalBytes < 0) {
            notes.add(
              'sessions.retention.maxTotalBytes: negative, clamped to 0 '
              '(no cap)',
            );
            maxTotalBytes = 0;
          }
        case 'minAgeDays':
          minAgeDays = _intWithNote(
            value,
            defaultMinAgeDays,
            'sessions.retention.minAgeDays',
            notes,
          );
          if (minAgeDays < 0) {
            notes.add(
              'sessions.retention.minAgeDays: negative, clamped to 0',
            );
            minAgeDays = 0;
          }
        case 'keepNamed':
          if (value is bool) {
            keepNamed = value;
          } else {
            notes.add(
              'sessions.retention.keepNamed: not a boolean, default applied',
            );
          }
        case 'sweep':
          final raw = '$value'.trim();
          final mode = switch (raw) {
            'boot' => SessionRetentionSweepMode.boot,
            'off' => SessionRetentionSweepMode.off,
            _ => null,
          };
          if (mode != null) {
            sweep = mode;
          } else {
            notes.add(
              'sessions.retention.sweep: "$raw" is not boot|off, '
              'default applied',
