    if (!hasExplicitValues) return '';
    final pad = ' ' * indent;
    final buffer = StringBuffer('${pad}retention:\n');
    final inner = ' ' * (indent + 2);
    if (maxTotalBytes != 0) buffer.write('$inner maxTotalBytes not written');
    return _renderRetentionBody(pad, inner);
