/// The gh-1746 boot retention check (AC7 + posture B): runs only when
/// the user touched the `sessions:` config section — a section-free
/// config stays byte-identical legacy (AC1). The report lines persist
/// to the boot log (fa.log) and the human-readable summary joins the
/// boot notice (dim line + TUI re-print, the roles-drop channel).
Future<void> _retentionBootCheck() async {
 final sessionsConfig = config.sessionsRetention;
 if (sessionsConfig == null) return;
 try {
   final report = await SessionRetentionSweper(
     fs: _env,
     sessionsRoot: config.sessionRoot,
     retention: sessionsConfig.retention,
     presenceStore: config.presenceStore,
     log: (line) => _logDiagnostic('[retention] $line'),
   ).enforceAtBoot();
   final lines = sessionSweepReportLines(report);
   for (final line in lines) {
     _logDiagnostic('[retention] $line');
   }
   if (lines.isNotEmpty) _retentionNotice = lines.join('\n');
 } on Object catch (error) {
   _logDiagnostic('[retention] boot check failed: $error');
 }
``
