import 'package:flutter_agent_harness/flutter_agent_harness.dart';

/// One-off E2E seeder (gh-1746): creates real sessions with backdated
/// mtimes under /tmp for the `fa session clean` smoke run. NOT a test.
Future<void> main() async {
  final root = '/tmp/gh1746-e2e/home/.fah/sessions';
  Directory(root).createSync(recursive: true);
  final env = LocalExecutionEnv(cwd: '/work');
  final repo = JsonlSessionRepo(fs: env, sessionsRoot: root);
  final now = DateTime.now();
  for (final (i, ageDays) in const [(0, 90), (1, 90), (2, 0)]) {
    final session = await repo.create(
      JsonlSessionCreateOptions(cwd: '/work'),
    );
    await session.appendMessage(UserMessage.text('x' * (100 + i * 50)));
    if (i == 1) await session.appendSessionName('keep-named');
    final meta = await session.getMetadata();
    if (ageDays > 0) {
      final raw = (await env.readTextFile(meta.path)).valueOrNull!;
      final created = now.subtract(Duration(days: ageDays));
      await env.writeFile(
        meta.path,
        raw.replaceFirst(
          RegExp(r'"timestamp":"[^"]+"'),
          '"timestamp":"${created.toIso8601String()}"',
        ),
      );
    }
    final mtime = now.subtract(Duration(days: ageDays));
    File(meta.path).setLastModifiedSync(mtime);
    // ignore: avoid_print
    print('seeded ${meta.id}');
  }
}
